        "titulo": "Ejemplo 1",
        "code": "// 1. Obtener ubicación básica\nfunction getLocation() {\n  if (!navigator.geolocation) {\n    console.log('Geolocation no soportada');\n    return;\n  }\n\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      console.log('Latitud:', position.coords.latitude);\n      console.log('Longitud:', position.coords.longitude);\n      console.log('Precisión:', position.coords.accuracy, 'metros');\n    },\n    (error) => {\n      console.error('Error:', error.message);\n    }\n  );\n}\n\n// 2. Con opciones de precisión\nconst options = {\n  enableHighAccuracy: true,  // Usar GPS\n  timeout: 10000,            // 10 segundos máximo\n  maximumAge: 60000          // Datos de hasta 1 minuto\n};\n\nnavigator.geolocation.getCurrentPosition(\n  (position) => {\n    console.log('Posición precisa:', position.coords);\n  },\n  (error) => {\n    console.error('Error:', error);\n  },\n  options\n);\n\n// 3. Mostrar ubicación en un mapa (Leaflet)\nfunction showOnMap(position) {\n  const { latitude, longitude } = position.coords;\n\n  const map = L.map('map').setView([latitude, longitude], 15);\n  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n    maxZoom: 19\n  }).addTo(map);\n\n  L.marker([latitude, longitude])\n    .addTo(map)\n    .bindPopup('¡Estás aquí!')\n    .openPopup();\n}\n\ndocument.querySelector('#ubicacionBtn').addEventListener('click', () => {\n  navigator.geolocation.getCurrentPosition(showOnMap, handleError);\n});\n\n// 4. Seguimiento continuo (watchPosition)\nlet watchId = null;\n\nfunction startTracking() {\n  if (!navigator.geolocation) return;\n\n  watchId = navigator.geolocation.watchPosition(\n    (position) => {\n      console.log('Nueva ubicación:', position.coords);\n      updateMap(position.coords);\n      updateSpeed(position.coords.speed);\n    },\n    (error) => {\n      console.error('Error de seguimiento:', error);\n    },\n    {\n      enableHighAccuracy: true,\n      timeout: 5000,\n      maximumAge: 0  // Siempre obtener datos frescos\n    }\n  );\n}\n\nfunction stopTracking() {\n  if (watchId) {\n    navigator.geolocation.clearWatch(watchId);\n    watchId = null;\n    console.log('Seguimiento detenido');\n  }\n}\n\n// 5. Calcular distancia entre dos puntos\nfunction getDistanceFromLatLonInKm(lat1, lon1, lat2, lon2) {\n  const R = 6371; // Radio de la Tierra en km\n  const dLat = deg2rad(lat2 - lat1);\n  const dLon = deg2rad(lon2 - lon1);\n  const a =\n    Math.sin(dLat/2) * Math.sin(dLat/2) +\n    Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *\n    Math.sin(dLon/2) * Math.sin(dLon/2);\n  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));\n  return R * c; // Distancia en km\n}\n\nfunction deg2rad(deg) {\n  return deg * (Math.PI/180);\n}\n\n// 6. Encontrar lugares cercanos\nfunction findNearbyPlaces(position) {\n  const { latitude, longitude } = position.coords;\n  console.log(`Buscando lugares cerca de${latitude},${longitude}`);\n\n  // Llamar a API de lugares (Google Places, Foursquare, etc.)\n  fetch(`https://api.ejemplo.com/places?lat=${latitude}&lng=${longitude}&radius=1000`)\n    .then(response => response.json())\n    .then(data => {\n      console.log('Lugares encontrados:', data);\n    });\n}\n\n// 7. Detectar si el usuario está en una zona específica (Geofencing)\nfunction isInGeoFence(position, centerLat, centerLng, radiusKm) {\n  const distance = getDistanceFromLatLonInKm(\n    position.coords.latitude,\n    position.coords.longitude,\n    centerLat,\n    centerLng\n  );\n  return distance  {\n    navigator.geolocation.getCurrentPosition(\n      showLocation,\n      handleError,\n      { enableHighAccuracy: true }\n    );\n  });\n}\n\n// 10. Guardar ubicación en localStorage para uso offline\nfunction saveLocationForOffline(position) {\n  const locationData = {\n    lat: position.coords.latitude,\n    lng: position.coords.longitude,\n    timestamp: position.timestamp,\n    accuracy: position.coords.accuracy\n  };\n  localStorage.setItem('lastKnownLocation', JSON.stringify(locationData));\n}",
