        "titulo": "Ejemplo 1",
        "code": "// 1. Obtener ubicación básica\nfunction getLocation() {\n  if (!navigator.geolocation) {\n    console.warn('Geolocation no soportada');\n    return;\n  }\n\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      const { latitude, longitude, accuracy } = position.coords;\n      console.log(`Ubicación:${latitude},${longitude}`);\n      console.log(`Precisión:${accuracy} metros`);\n    },\n    (error) => {\n      console.error('Error:', error.message);\n    }\n  );\n}\n\n// 2. Con opciones completas\nconst options = {\n  enableHighAccuracy: true,  // GPS para máxima precisión\n  timeout: 15000,            // 15 segundos máximo\n  maximumAge: 30000          // Usar datos de hasta 30 segundos\n};\n\nnavigator.geolocation.getCurrentPosition(\n  (position) => {\n    console.log('Posición precisa obtenida:', position.coords);\n    updateUI(position);\n  },\n  (error) => {\n    console.error('Error obteniendo ubicación:', error.message);\n    showFallbackUI();\n  },\n  options\n);\n\n// 3. Mostrar en mapa (Google Maps)\nfunction initMap() {\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      const { latitude, longitude } = position.coords;\n      const map = new google.maps.Map(document.getElementById('map'), {\n        center: { lat: latitude, lng: longitude },\n        zoom: 15\n      });\n\n      new google.maps.Marker({\n        position: { lat: latitude, lng: longitude },\n        map: map,\n        title: '¡Estás aquí!'\n      });\n    },\n    () => {\n      // Fallback: Mapa con ubicación por defecto\n      const map = new google.maps.Map(document.getElementById('map'), {\n        center: { lat: 40.4168, lng: -3.7038 },\n        zoom: 10\n      });\n    }\n  );\n}\n\n// 4. Calcular distancia al punto de destino\nfunction calculateDistanceToDestination() {\n  const destination = { lat: 40.4168, lng: -3.7038 }; // Madrid\n\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      const { latitude, longitude } = position.coords;\n      const distance = getDistanceFromLatLonInKm(\n        latitude, longitude,\n        destination.lat, destination.lng\n      );\n\n      console.log(`Distancia:${distance.toFixed(2)} km`);\n      showDistanceUI(distance);\n    },\n    (error) => {\n      console.error('Error:', error);\n    }\n  );\n}\n\n// Función de distancia (Haversine)\nfunction getDistanceFromLatLonInKm(lat1, lon1, lat2, lon2) {\n  const R = 6371;\n  const dLat = (lat2 - lat1) * Math.PI / 180;\n  const dLon = (lon2 - lon1) * Math.PI / 180;\n  const a =\n    Math.sin(dLat/2) * Math.sin(dLat/2) +\n    Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *\n    Math.sin(dLon/2) * Math.sin(dLon/2);\n  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));\n  return R * c;\n}\n\n// 5. Manejador de errores completo\nfunction handleLocationError(error) {\n  const errorMessages = {\n    1: 'Permiso denegado por el usuario',\n    2: 'Posición no disponible (GPS sin señal)',\n    3: 'Tiempo de espera agotado'\n  };\n\n  const message = errorMessages[error.code] || 'Error desconocido';\n  console.error(`${message}:${error.message}`);\n\n  // Mostrar UI de error\n  document.querySelector('#locationStatus').textContent = message;\n  document.querySelector('#locationStatus').className = 'error';\n}\n\n// 6. Con UI feedback\ndocument.querySelector('#locationBtn').addEventListener('click', () => {\n  const statusElement = document.querySelector('#status');\n  statusElement.textContent = 'Obteniendo ubicación...';\n  statusElement.className = 'loading';\n\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      statusElement.textContent = '¡Ubicación obtenida!';\n      statusElement.className = 'success';\n      displayLocation(position.coords);\n    },\n    (error) => {\n      statusElement.textContent = 'No se pudo obtener la ubicación';\n      statusElement.className = 'error';\n      handleLocationError(error);\n    },\n    { timeout: 10000 }\n  );\n});\n\n// 7. Con fallback a IP geolocation\nfunction getLocationWithFallback() {\n  navigator.geolocation.getCurrentPosition(\n    (position) => {\n      // Usar GPS\n      processLocation(position.coords);\n    },\n    async () => {\n      // Fallback a IP\n      console.log('Usando geolocalización por IP');\n      try {\n        const response = await fetch('https://ipapi.co/json/');\n        const data = await response.json();\n        processLocation({\n          latitude: data.latitude,\n          longitude: data.longitude,\n          accuracy: 10000 // IP es menos precisa\n        });\n      } catch (error) {\n        console.error('Todos los métodos fallaron');\n        useDefaultLocation();\n      }\n    }\n  );\n}\n\n// 8. Cachear ubicación para uso futuro\nfunction getCachedOrCurrentLocation() {\n  const cached = localStorage.getItem('userLocation');\n\n  if (cached) {\n    const data = JSON.parse(cached);\n    const age = Date.now() - data.timestamp;\n    if (age  {\n    navigator.geolocation.getCurrentPosition(\n      (position) => {\n        const coords = position.coords;\n        localStorage.setItem('userLocation', JSON.stringify({\n          coords: coords,\n          timestamp: Date.now()\n        }));\n        resolve(coords);\n      },\n      (error) => reject(error)\n    );\n  });\n}\n\n// 9. Obtener dirección real (reverse geocoding)\nfunction getAddressFromLocation() {\n  navigator.geolocation.getCurrentPosition(\n    async (position) => {\n      const { latitude, longitude } = position.coords;\n\n      // Usando Nominatim (OpenStreetMap) para reverse geocoding\n      const response = await fetch(\n        `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json`\n      );\n      const data = await response.json();\n      const address = data.display_name;\n\n      console.log('Dirección:', address);\n      displayAddress(address);\n    },\n    handleLocationError\n  );\n}\n\n// 10. Verificar soporte y permisos\nasync function checkLocationSupport() {\n  // 1. Verificar soporte de API\n  if (!navigator.geolocation) {\n    return { supported: false, reason: 'API no soportada' };\n  }\n\n  // 2. Verificar permisos (más moderno)\n  if (navigator.permissions) {\n    try {\n      const result = await navigator.permissions.query({ name: 'geolocation' });\n      return {\n        supported: true,\n        permission: result.state, // 'granted', 'denied', 'prompt'\n        canRequest: result.state !== 'denied'\n      };\n    } catch (error) {\n      // Permissions API no soportada, solo intentar\n      return { supported: true, permission: 'unknown', canRequest: true };\n    }\n  }\n\n  return { supported: true, permission: 'unknown', canRequest: true };\n}",
